function load(){try{const x=JSON.parse(localStorage.getItem(storeKey)||'null');return Array.isArray(x)&&x.every(v=>v?.id&&v.name&&v.command)?x:structuredClone(defaults)}catch{return structuredClone(defaults)}}
let commands=load(),currentTree='main',selected=null,editingId=null,instances={};
const legacyBuiltinNames={"dev": "Web \u5f00\u53d1\u670d\u52a1", "java": "Java API", "test": "\u8fd0\u884c\u5355\u5143\u6d4b\u8bd5", "build": "\u6784\u5efa\u53d1\u5e03\u5305"};
for(const entry of commands){const builtin=defaults.find(item=>item.id===entry.id);if(builtin&&entry.name===legacyBuiltinNames[entry.id])entry.name=builtin.name}
const trees={main:'D:\\project\\ThreadTerm\\ThreadTerm-v3',feature:'D:\\project\\ThreadTerm\\ThreadTerm-v3-api'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>commands.find(x=>x.id===id); const active=r=>r&&['starting','running'].includes(r.state);
function persist(){localStorage.setItem(storeKey,JSON.stringify(commands))} function resolveCwd(c){return !c||c==='.'?trees[currentTree]:`${trees[currentTree]}\\${c.replace(/^\.\\?/,'')}`}
function renderCommands(){const q=$('commandSearch').value.trim().toLowerCase(),list=$('commandList');let html='';for(const s of ['project','global']){const rows=commands.filter(x=>x.scope===s&&`${x.name} ${x.command}`.toLowerCase().includes(q));if(!rows.length)continue;html+=`<div class="command-group-title">${s==='project'?'This project':'Global commands'}</div>`+rows.map(x=>{const live=instances[`${currentTree}:${x.id}`];const open=active(live);return `<div class="command-row"><button data-run="${x.id}" title="${open?'Open existing terminal':'Run '+esc(x.name)}"><span class="star">${x.favorite?'★':'☆'}</span><span><b>${esc(x.name)}</b><code>${esc(x.command)}</code></span><span class="scope">${open?'Running · Open terminal':esc(x.shell)}</span></button><button class="command-edit" data-edit="${x.id}" aria-label="Edit ${esc(x.name)}">Edit</button></div>`}).join('')}list.innerHTML=html||'<p class="menu-context">No matching commands</p>';list.querySelectorAll('[data-run]').forEach(x=>x.onclick=()=>launch(byId(x.dataset.run)));list.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>openDialog(byId(x.dataset.edit)))}
function shellHeader(r){return r.shell==='CMD'?['Microsoft Windows [Version 10.0.22631.0]',`${r.cwd}> ${r.command}`]:['Windows PowerShell',`PS ${r.cwd}> ${r.command}`]}
function log(r,lines){r.lines=[...shellHeader(r),'',...lines];if(selected===r)$('terminalOutput').textContent=r.lines.join('\n')}
function label(r){if(!r)return 'Idle · Not started';if(r.state==='starting')return 'Starting · Waiting for port evidence';if(r.state==='running')return r.ready?'Running · Listening port detected':'Running · Port not ready';if(r.state==='complete')return 'Completed · Exit code 0';return r.state==='failed'?'Launch failed':'Stopped'}
function strip(a,b,on=false){$('stripTitle').textContent=a;$('stripText').textContent=b;$('stripDot').className=`status-dot ${on?'running':''}`}
 function draw(){const r=selected,closed=r?.closed,running=active(r),canPreview=r?.state==='running'&&r.ready,port=r?.type==='java'?8080:5173;$('terminalTitle').textContent=r?.name||'Terminal';$('tabName').textContent=r?.name||'Terminal';$('terminalStatus').textContent=label(r);$('navTerminalName').textContent=r?.name||'No active terminal';$('navTerminalMeta').textContent=label(r);$('navDot').className=`status-dot ${running?'running':''}`;$('stopRun').disabled=!running;$('stopRun').textContent=running?'Stop':'Ended';$('tabDot').textContent=running?'●':'○';$('promptShell').textContent=r?.shell==='CMD'?'':'PS';$('promptCwd').textContent=r?.cwd||trees[currentTree];$('terminalOutput').textContent=r?.lines?.join('\n')||`PS ${trees[currentTree]}>\n\nChoose a quick command to start a foreground process.`;$('terminalNav').classList.toggle('active',!!r&&!closed);$('openTerminal').textContent=closed?'↗ Open terminal':'＋ New terminal';$('closedTerminal').classList.toggle('hidden',!closed);document.querySelector('.terminal-panel').classList.toggle('hidden',!!closed);$('closedTerminalText').textContent=r?`${r.name} ${running?'is still running':'Ended'}; closing the view does not change this run.`:'';
 if(!r)strip('Quick Launch is ready','Choose a command to launch as a foreground process in a terminal.');else if(closed)strip(`${r.name} ${running?'is still running':'view closed'}`,'The terminal view is closed. Reopen it without interrupting the process.',running);else if(r.state==='starting')strip(`${r.name} is starting`,'Terminal created; waiting for a listening port.',true);else if(r.state==='running')strip(`${r.name} is running`,r.ready?'Listening port detected; simulated preview is available.':'The process has started; no port evidence yet.',true);else if(r.state==='complete')strip(`${r.name} completed`,'The one-shot task exited with code 0.');else if(r.state==='failed')strip(`${r.name} did not start`,r.message);else strip(`${r.name} stopped`,'This simulated run was stopped.');
 $('openPreview').disabled=!canPreview;$('previewStatus').textContent=canPreview?'Preview available · Listening port detected':'Waiting for port evidence';$('previewBody').classList.toggle('preview-ready',!!canPreview);$('previewTitle').textContent=canPreview?'Preview available':'Preview unavailable';$('previewText').textContent=canPreview?'A listening port was detected. You can open the preview; this does not confirm application health or a successful page response.':'A running process does not confirm an accessible service. Preview becomes available after port evidence.';$('portProof').textContent=canPreview?`Port evidence: localhost:${port} is listening`:'No listening port detected';$('previewUrl').textContent=`http://localhost:${port}/`;$('previewFrame').classList.toggle('hidden',!canPreview);$('mockFix').classList.toggle('hidden',!(r?.state==='failed'&&$('scenario').value==='java'))}
function timers(r){(r?.timers||[]).forEach(clearTimeout);if(r)r.timers=[]} function rerender(r){if(selected===r)draw()} function fail(r,head,help){if(r.state==='stopped')return;r.state='failed';r.ready=false;r.message=help;log(r,[head,'',help]);rerender(r)}
function launch(def,{force=false}={}){if(!def)return;$('quickMenu').classList.add('hidden');$('quickToggle').setAttribute('aria-expanded','false');const key=`${currentTree}:${def.id}`,old=instances[key];if(old&&active(old)&&!force){selected=old;old.closed=false;draw();return}if(old&&force){timers(old);old.state='stopped';old.ready=false;log(old,['Prototype scenario reset this prior simulation.'])}const snap=structuredClone(def),r={key,tree:currentTree,id:def.id,name:snap.name,command:snap.command,shell:snap.shell,cwd:resolveCwd(snap.cwd),type:snap.type,definition:snap,state:'starting',ready:false,closed:false,timers:[],lines:[]};instances[key]=r;selected=r;log(r,['Starting foreground command in a fresh inherited environment…']);draw();if(r.type==='oneshot'){r.timers.push(setTimeout(()=>{r.state='complete';log(r,[`> ${r.name}`,'All checks passed.','Process exited with code 0.']);rerender(r)},800));return}if($('scenario').value==='script'&&r.type==='node'){r.timers.push(setTimeout(()=>fail(r,'npm error Missing script: "dev"','Run "npm run" to list scripts, then edit this command or choose an available script.'),450));return}if($('scenario').value==='java'&&r.type==='java'){r.timers.push(setTimeout(()=>fail(r,'No Java found: PATH has no java and JAVA_HOME is unset or invalid.','Fix the mock environment, or configure a valid JAVA_HOME / PATH, then retry.'),450));return}r.timers.push(setTimeout(()=>{if(r.state!=='starting')return;r.state='running';log(r,[r.type==='java'?':: Spring Boot ::':'VITE v6.0.0 ready in 428 ms','Waiting for a listening port…']);rerender(r);r.timers.push(setTimeout(()=>{if(r.state!=='running')return;r.ready=true;const port=r.type==='java'?8080:5173;log(r,[r.type==='java'?':: Spring Boot ::':'VITE v6.0.0 ready in 428 ms',`Local: http://localhost:${port}/`,`Port evidence: localhost:${port} LISTENING`]);rerender(r)},850))},450))}
function switchTree(t){currentTree=t;document.querySelectorAll('.worktree').forEach(x=>x.classList.toggle('active',x.dataset.worktree===t));$('treeLabel').textContent=t;$('menuTree').textContent=t;$('cwdLabel').textContent=trees[t];selected=Object.values(instances).find(x=>x.tree===t&&active(x))||null;draw()}
function openDialog(d){editingId=d?.id||null;d=d||{name:'',command:'',scope:'project',shell:'PowerShell',cwd:'.',favorite:false,type:'custom',env:{inherit:true,javaHome:'',extraPath:''}};$('dialogTitle').textContent=editingId?'Edit Quick Launch command':'New Quick Launch command';$('fName').value=d.name;$('fCommand').value=d.command;$('fScope').value=d.scope;$('fShell').value=d.shell;$('fType').value=d.type==='oneshot'?'oneshot':'custom';$('fCwd').value=d.cwd||'.';$('fFavorite').checked=!!d.favorite;$('fInherit').checked=d.env?.inherit!==false;$('fJavaHome').value=d.env?.javaHome||'';$('fExtraPath').value=d.env?.extraPath||'';$('commandDialog').showModal();$('fName').focus()}
function saveDefinition(){const old=editingId&&byId(editingId),type=$('fType').value==='oneshot'?'oneshot':(old&&old.type!=='oneshot'?old.type:'custom'),next={id:old?.id||`custom-${Date.now()}`,name:$('fName').value.trim(),command:$('fCommand').value.trim(),scope:$('fScope').value,shell:$('fShell').value,cwd:$('fCwd').value.trim()||'.',favorite:$('fFavorite').checked,type,env:{inherit:$('fInherit').checked,javaHome:$('fJavaHome').value.trim(),extraPath:$('fExtraPath').value.trim()}};if(old)Object.assign(old,next);else commands.unshift(next);persist();renderCommands();return next}
 $('quickToggle').onclick=()=>{const hidden=$('quickMenu').classList.toggle('hidden');$('quickToggle').setAttribute('aria-expanded',String(!hidden));if(!hidden){renderCommands();$('commandSearch').focus()}};$('commandSearch').oninput=renderCommands;document.addEventListener('click',e=>{if(!e.target.closest('.quick-wrap')){$('quickMenu').classList.add('hidden');$('quickToggle').setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const menuOpen=!$('quickMenu').classList.contains('hidden');$('quickMenu').classList.add('hidden');$('quickToggle').setAttribute('aria-expanded','false');if(menuOpen)$('quickToggle').focus();if($('commandDialog').open)$('commandDialog').close()}});
document.querySelectorAll('.worktree').forEach(b=>b.onclick=()=>switchTree(b.dataset.worktree));$('theme').onclick=()=>{const dark=document.body.classList.toggle('dark');$('theme').textContent=dark?'Light':'Dark';$('theme').setAttribute('aria-pressed',String(dark))};$('scenario').onchange=()=>launch(byId($('scenario').value==='java'?'java':'dev'),{force:true});$('mockFix').onclick=()=>{$('scenario').value='node';launch(byId('java'),{force:true})};$('newCommand').onclick=()=>openDialog();$('manageCommand').onclick=()=>openDialog(commands[0]);$('dialogClose').onclick=$('dialogCancel').onclick=()=>$('commandDialog').close();$('commandForm').addEventListener('submit',e=>{e.preventDefault();saveDefinition();$('commandDialog').close()});$('saveAndRun').onclick=()=>{const form=$('commandForm');if(!form.reportValidity())return;const saved=saveDefinition();$('commandDialog').close();launch(saved)};$('stopRun').onclick=()=>{if(active(selected)){timers(selected);selected.state='stopped';selected.ready=false;log(selected,['^C','Run stopped by user.']);draw()}};$('closeTerminal').onclick=()=>{if(selected){selected.closed=true;draw()}};$('reopenTerminal').onclick=()=>{if(selected){selected.closed=false;draw()}};$('openTerminal').onclick=()=>{if(selected){selected.closed=false;draw()}else $('quickToggle').click()};$('stripOpen').onclick=()=>$('openTerminal').click();$('terminalNav').onclick=()=>$('openTerminal').click();$('tabAdd').onclick=()=>$('quickToggle').click();$('openPreview').onclick=()=>{if(selected?.ready)$('previewFrame').scrollIntoView({behavior:'smooth',block:'center'})};
